"use client";
import { useEffect, useRef, useState } from "react";
import * as THREE from "three";
import { OrbitControls } from "three/examples/jsm/controls/OrbitControls.js";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
import { USDLoader } from "three/examples/jsm/loaders/USDLoader.js";

export type ScanSize = { widthM: number; depthM: number; heightM: number };

/**
 * Shows the owner's own 3D scan (USDZ from Reality Composer / Object Capture, or GLB). Not generated by AI.
 * The measured size is the model's bounding box, reported through onSize; apps like Reality Composer export in meters.
 */
export default function ScanViewer({ url, format, title, onSize }: { url: string; format: "glb" | "usdz"; title: string; onSize?: (s: ScanSize) => void }) {
  const host = useRef<HTMLDivElement>(null);
  const [state, setState] = useState<"loading" | "ready" | "error">("loading");
  const cb = useRef(onSize); cb.current = onSize;

  useEffect(() => {
    const el = host.current;
    if (!el) return;
    let disposed = false, raf = 0;
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    el.appendChild(renderer.domElement);
    const scene = new THREE.Scene();
    scene.add(new THREE.HemisphereLight(0xffffff, 0x8a7a60, 1.6));
    const sun = new THREE.DirectionalLight(0xffffff, 1.6); sun.position.set(2, 4, 3); scene.add(sun);
    const camera = new THREE.PerspectiveCamera(40, 1, 0.01, 100);
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    const resize = () => { const w = el.clientWidth, h = el.clientHeight; renderer.setSize(w, h); camera.aspect = w / h; camera.updateProjectionMatrix(); };
    resize();
    const ro = new ResizeObserver(resize); ro.observe(el);

    const onLoaded = (obj: THREE.Object3D) => {
      if (disposed) return;
      const box = new THREE.Box3().setFromObject(obj);
      const size = box.getSize(new THREE.Vector3()), center = box.getCenter(new THREE.Vector3());
      cb.current?.({ widthM: size.x, depthM: size.z, heightM: size.y });
      obj.position.sub(center); // centre it; sizes were read before so scale is untouched
      scene.add(obj);
      const r = Math.max(size.x, size.y, size.z) || 1;
      camera.position.set(r * 1.4, r * 1.0, r * 1.8); controls.target.set(0, 0, 0); controls.update();
      setState("ready");
    };
    const onError = () => { if (!disposed) setState("error"); };
    if (format === "glb") new GLTFLoader().load(url, (g) => onLoaded(g.scene), undefined, onError);
    else new USDLoader().load(url, onLoaded, undefined, onError);

    const tick = () => { raf = requestAnimationFrame(tick); controls.update(); renderer.render(scene, camera); };
    tick();
    return () => { disposed = true; cancelAnimationFrame(raf); ro.disconnect(); controls.dispose(); renderer.dispose(); renderer.domElement.remove(); };
  }, [url, format]);

  return (
    <div className="relative h-72 overflow-hidden rounded-2xl bg-sunken" data-testid="scan-viewer" data-state={state}>
      <div ref={host} className="absolute inset-0" role="img" aria-label={`3D scan of ${title}. Drag to turn it.`} />
      {state === "loading" && <p className="absolute inset-0 flex items-center justify-center text-sm text-muted">Loading the 3D scan…</p>}
      {state === "error" && <p role="alert" className="absolute inset-0 flex items-center justify-center p-4 text-center text-sm text-bad">We couldn't open this scan. Try exporting it again as .usdz or .glb.</p>}
    </div>
  );
}
